const defaults = { theme: "light" };

function readTheme(storage) {
  try {
    const raw = storage.getItem("app:theme");
    return raw === "dark" || raw === "light" ? raw : defaults.theme;
  } catch (error) {
    return defaults.theme;
  }
}

function saveTheme(storage, theme) {
  try {
    storage.setItem("app:theme", theme);
    return true;
  } catch (error) {
    return false;
  }
}

const key = "app:preferences";

try {
  localStorage.setItem(key, JSON.stringify({ theme: "dark" }));
} catch (error) {
  console.warn("Preference was not persisted", error);
}

window.addEventListener("storage", (event) => {
  if (event.key === key && event.newValue !== null) {
    console.log(JSON.parse(event.newValue).theme);
  }
});

const request = indexedDB.open("notes", 1);

request.onupgradeneeded = () => {
  const db = request.result;
  if (!db.objectStoreNames.contains("drafts")) {
    const store = db.createObjectStore("drafts", { keyPath: "id" });
    store.createIndex("by-updated", "updatedAt");
  }
};

request.onsuccess = () => {
  const db = request.result;
  db.onversionchange = () => db.close();
  console.log("database is ready");
};

request.onerror = () => console.error(request.error);

function saveDraft(db, draft) {
  const transaction = db.transaction("drafts", "readwrite");
  const store = transaction.objectStore("drafts");
  store.put(draft);

  transaction.oncomplete = () => console.log("committed");
  transaction.onabort = () => console.error(transaction.error);
  transaction.onerror = () => console.error("request or transaction failed");
}

